head.script:
scwin.tabControl1_ontabclick = function(tabID, idx) {
    //alert("tab-event발생");
    window.log = "tab-event발생";
};
scwin.trigger2_onclick = function(e) {
    grd.setDisabled("grid", true);
    alert("grid-disabled");
};
scwin.trigger1_onclick = function(e) {
    tabControl1.disableTab(0);
    //alert("tab-disabled");
    window.log1 = "tab-disabled";
};
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Test step 1. 샘플파일을 실행 후 좌측상단의 탭을 마우스로 클릭한다.
    //1. Run the sample file and click the tab in the upper left corner.
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('tabControl1_tab_tabs1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify  1. tab-event발생 알림창이 보여진다.
    // 1. A tab-event notification window is displayed.
    WebSquare.wUnit.addCommand("assert", "window.log", "tab-event발생");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 2. 우측하단의 tab-disable버튼을 클릭한다.
    //2. Click the tab-disable button in the lower right corner.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 2. tab이 비활성화 되면서 tab-disabled 알림창이 보여진다.
    //2. The tab is disabled and a tab-disabled notification window is displayed.
    WebSquare.wUnit.addCommand("assert", "window.log1", "tab-disabled");
    WebSquare.wUnit.addCommand("pause", "500");
    //Test step 3. 좌측상단의 disable된 탭을 다시 마우스로 클릭한다.
    //3. Click the disabled tab in the upper left corner again with the mouse.
    WebSquare.wUnit.addCommand("set", "window.log = undefined");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('tabControl1_tab_tabs1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify 3. 아무반응도 일어나지 않는다.(이전에는 알림창 발생함)
    //3. No response occurs (previously a notification window appears).
    WebSquare.wUnit.addCommand("assert", "window.log == 'tab-event발생'", "false");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    window.log = undefined;
	window.log1 = undefined;
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 09-Mar-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
